"""Original Streamlit styling inspired by the supplied Paper Dashboard reference."""
import streamlit as st

def apply_theme():
    st.markdown('''<style>
:root{--ink:#252422;--paper:#f4f3ef;--lime:#7ac29a;--lilac:#68b3c8;}
html,body,.stApp{font-family:'Segoe UI',Arial,sans-serif!important;background:#f4f3ef!important;color:#252422!important;}[data-testid="stHeader"]{background:#f4f3eff2!important;border-bottom:1px solid #ddd9cf;}[data-testid="stMainBlockContainer"]{max-width:1500px;padding:2.5rem 2.2rem!important;}
h1,h2,h3{font-family:'Segoe UI',Arial,sans-serif!important;color:#252422!important;letter-spacing:-.5px!important;font-weight:400!important;}h1{font-size:30px!important;line-height:1.25!important;margin:8px 0 12px!important;}h2{font-size:24px!important;}h3{font-size:20px!important;}p,label{color:#66615b;}[data-testid="stCaptionContainer"]{color:#9a958c!important;}
[data-testid="stSidebar"]{background:#fff!important;border-right:1px solid #ddd9cf!important;}[data-testid="stSidebar"] p,[data-testid="stSidebar"] label,[data-testid="stSidebar"] h2{color:#66615b!important;}[data-testid="stSidebar"] h2{font-size:24px!important;text-transform:uppercase;letter-spacing:1px!important;border-bottom:1px solid #eee;padding-bottom:20px;}[data-testid="stSidebar"] [role="radiogroup"]{gap:7px;}[data-testid="stSidebar"] [role="radio"]{accent-color:#eb5e28;}[data-testid="stSidebar"] label:has(input:checked){background:#faf4ea;border-radius:6px;color:#eb5e28!important;}
.sidebar-sticker,.vibe-ribbon,.floating-vibes,.section-kicker{display:none!important;}[data-testid="stMetric"]{border:0!important;border-radius:6px!important;background:#fff!important;box-shadow:0 6px 10px -4px #00000026!important;padding:20px!important;min-height:125px;}[data-testid="stMetricLabel"]{color:#9a958c!important;font-size:13px;}[data-testid="stMetricValue"]{font-size:30px!important;font-weight:400!important;color:#252422!important;letter-spacing:-.7px;}
[data-testid="stVerticalBlockBorderWrapper"]>div,[data-testid="stExpander"]{background:#fff;border:0!important;border-radius:6px!important;box-shadow:0 6px 10px -4px #00000020;}[data-testid="stExpander"]{margin:8px 0 15px;}[data-testid="stExpander"] summary{padding:15px!important;}[data-testid="stAlert"]{border:0!important;border-radius:5px!important;font-size:13px;}
.stButton>button,.stFormSubmitButton>button{border-radius:20px!important;border:1px solid #b8b1a8!important;color:#66615b!important;background:#fff!important;box-shadow:none!important;padding:8px 17px!important;font-weight:500!important;}.stButton>button[kind="primary"],.stFormSubmitButton>button[kind="primary"]{background:#eb5e28!important;color:white!important;border-color:#eb5e28!important;}.stButton>button:hover,.stFormSubmitButton>button:hover{background:#f3eee7!important;border-color:#eb5e28!important;color:#eb5e28!important;}
[data-baseweb="input"],[data-baseweb="textarea"],[data-baseweb="select"]>div{background:#fff!important;border-radius:5px!important;border-color:#ddd9cf!important;color:#66615b!important;}input,textarea{color:#66615b!important;}[data-testid="stDataFrame"]{border-radius:6px;overflow:hidden;}
.meme-note,.wallet-chat,.reaction-receipts,.verdict,.pass-card,.planning-win,.boarding-ticket{border:0!important;background:#fff!important;border-radius:6px!important;box-shadow:0 6px 10px -4px #00000026!important;color:#252422!important;padding:22px!important;}.meme-note strong,.verdict h2,.pass-card h2{color:#252422!important;}.meme-note p,.verdict p,.pass-card p{color:#9a958c!important;}.hero-kicker,.meme-label{color:#eb5e28!important;}.verdict.tight{border-top:3px solid #f3bb45!important;}.verdict.good,.pass-card{border-top:3px solid #7ac29a!important;}.chat-message>div{background:#f4f3ef!important;border:0!important;}.chat-message.outgoing>div{background:#e5f0f3!important;}.chat-message p,.chat-message small{color:#66615b!important;}.receipt-polaroid{border:0!important;box-shadow:0 6px 10px -4px #0003!important;transform:none!important;}.paper-topline{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ddd9cf;padding:0 0 15px;margin-bottom:20px;color:#9a958c;font-size:12px;letter-spacing:.5px;}.paper-topline strong{font-weight:500;color:#66615b;font-size:16px;}.paper-summary{margin:18px 0 25px;padding:16px 20px;background:#fff;border-radius:6px;box-shadow:0 6px 10px -4px #00000020;border-left:3px solid #68b3c8;font-size:14px;color:#66615b;}
@media(max-width:750px){[data-testid="stMainBlockContainer"]{padding:1.4rem 1rem!important;}h1{font-size:27px!important;}[data-testid="stMetric"]{min-height:105px;padding:16px!important;}[data-testid="stMetricValue"]{font-size:26px!important;}.paper-topline{font-size:10px;}}
</style>''',unsafe_allow_html=True)


